import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { router } from 'kea-router'

import { teamLogic } from 'scenes/teamLogic'

import { betsRetrieve } from '../generated/api'
import type { BetsSpendPointApi } from '../generated/api.schemas'

const FRESH_FOR_MS = 30000

export interface BetsSidebarPreviewState {
    open: boolean
    suppressed: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface betsSidebarPreviewLogicValues {
    currentProjectId: number | string // teamLogic
    spendHistories: Record<string, BetsSpendPointApi[]>
    preview: BetsSidebarPreviewState
    previewOpen: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface betsSidebarPreviewLogicActions {
    loadSpendHistory: (id: string) => {
        id: string
    }
    setSpendHistory: (
        id: string,
        history: BetsSpendPointApi[]
    ) => {
        id: string
        history: BetsSpendPointApi[]
    }
    previewOpenChanged: (open: boolean) => {
        open: boolean
    }
    closePreview: () => {
        value: true
    }
    suppressPreview: () => {
        value: true
    }
    releasePreview: () => {
        value: true
    }
}

export type betsSidebarPreviewLogicType = MakeLogicType<
    betsSidebarPreviewLogicValues,
    betsSidebarPreviewLogicActions,
    Record<string, any>
>

export const betsSidebarPreviewLogic = kea<betsSidebarPreviewLogicType>([
    path(['products', 'bets', 'betsSidebarPreviewLogic']),
    connect({ values: [teamLogic, ['currentProjectId']] }),
    actions({
        loadSpendHistory: (id: string) => ({ id }),
        setSpendHistory: (id: string, history: BetsSpendPointApi[]) => ({ id, history }),
        previewOpenChanged: (open: boolean) => ({ open }),
        closePreview: true,
        suppressPreview: true,
        releasePreview: true,
    }),
    reducers({
        spendHistories: [
            {} as Record<string, BetsSpendPointApi[]>,
            { setSpendHistory: (state, { id, history }) => ({ ...state, [id]: history }) },
        ],
        preview: [
            { open: false, suppressed: false } as BetsSidebarPreviewState,
            {
                previewOpenChanged: (state, { open }) => ({ ...state, open: open && !state.suppressed }),
                closePreview: (state) => ({ ...state, open: false }),
                suppressPreview: () => ({ open: false, suppressed: true }),
                releasePreview: (state) => ({ ...state, suppressed: false }),
                [router.actionTypes.locationChanged]: (state) => ({ ...state, open: false }),
            },
        ],
    }),
    selectors({
        previewOpen: [(s) => [s.preview], (preview: BetsSidebarPreviewState): boolean => preview.open],
    }),
    listeners(({ actions, values, cache }) => ({
        loadSpendHistory: async ({ id }) => {
            cache.readAt ??= {} as Record<string, number>
            if (Date.now() - (cache.readAt[id] ?? 0) < FRESH_FOR_MS) {
                return
            }
            cache.readAt[id] = Date.now()
            try {
                const bet = await betsRetrieve(String(values.currentProjectId), id)
                actions.setSpendHistory(id, bet.spend_history)
            } catch {
                cache.readAt[id] = 0
            }
        },
    })),
])
